public static double moyenne(int[] notes) {
    if (notes.length == 0) {
        return 0;
    }
    int somme = 0;
    for (int n : notes) {
        somme += n;
    }
    return (double) somme / notes.length;
}

// moyenne(new int[]{12, 15, 9}) vaut 12.0

#include <vector>

double moyenne(const std::vector<int>& notes) {
    if (notes.empty()) {
        return 0.0;
    }
    int somme = 0;
    for (int n : notes) {
        somme += n;
    }
    return static_cast<double>(somme) / notes.size();
}

